import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';
import { Line2 } from 'three/examples/jsm/lines/Line2.js';
import { LineMaterial } from 'three/examples/jsm/lines/LineMaterial.js';
import { LineGeometry } from 'three/examples/jsm/lines/LineGeometry.js';
import { RGBELoader } from 'three/examples/jsm/loaders/RGBELoader.js';
import { CSS2DRenderer, CSS2DObject } from 'three/examples/jsm/renderers/CSS2DRenderer.js';

const txt = (function () {
    const textureLoader = new THREE.TextureLoader();
    return function (name, colorSpace = false) {
        const texture = textureLoader.load(name);
        if (false === colorSpace) texture.colorSpace = THREE.SRGBColorSpace;
        else texture.colorSpace = colorSpace;
        return texture;
    };
})();

const { PI, sin, cos } = Math;
const deg = PI / 180;
const origin = new THREE.Vector3(0, 0, 0);
const axis_x = new THREE.Vector3(1, 0, 0);
const axis_y = new THREE.Vector3(0, 1, 0);
const axis_z = new THREE.Vector3(0, 0, 1);

const scene = new THREE.Scene();
scene.add(new THREE.AxesHelper(100));
scene.add(new THREE.AmbientLight(0xffffff, 0.5));

const sun = new THREE.PointLight(0xffffff, 10, 1000, 1);
sun.castShadow = true;

const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: txt('textures/sun.png') }));
let sc = 1;
sprite.scale.set(sc, sc, sc);
sun.add(sprite);
scene.add(sun);

const plane = new THREE.Mesh(
    new THREE.PlaneGeometry(100, 100),
    new THREE.MeshPhysicalMaterial({ color: 0xffffff, side: THREE.DoubleSide })
);
plane.castShadow = false;
plane.receiveShadow = true;
plane.rotateX(90 * deg);
scene.add(plane);

const gnomon = new THREE.Mesh(
    new THREE.CylinderGeometry(0.1, 0.1, 1, 32, 1, false),
    new THREE.MeshPhysicalMaterial({ color: 0xdeb887 })
);
gnomon.castShadow = true;
gnomon.receiveShadow = true;
gnomon.position.y = 0.5;
scene.add(gnomon);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 1e3);
camera.position.set(7, 10, 7);
scene.add(camera);
camera.updateProjectionMatrix();

const renderer = new THREE.WebGLRenderer({
    canvas: document.querySelector('#canvas'),
    logarithmicDepthBuffer: true,
    outputColorSpace: THREE.SRGBColorSpace,
    antialias: true,
    autoClear: false,
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(window.devicePixelRatio ? window.devicePixelRatio : 1);
renderer.setClearColor(0x000000, 0);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;


const orbitControls = new OrbitControls(camera, renderer.domElement);
// orbitControls.enablePan = false;
// orbitControls.minDistance = earth_display_radius * 1.5;
// orbitControls.maxDistance = star_distance * 3;

window.addEventListener('resize', function () {
    const ww = window.innerWidth;
    const wh = window.innerHeight;
    camera.aspect = ww / wh;
    camera.updateProjectionMatrix();
    renderer.setSize(ww, wh);
});

let index = 0;
let past = 0;
let pointer;
function reanimate(now) {
    orbitControls.update();
    renderer.render(scene, camera);
    const delta = now - past;
    if (1000 / 60 <= delta) {
        past = now;
        const sunpos = new THREE.Vector3(10, 0, 0);
        const alt = data[index].altitude;
        const azi = data[index].azimuth;
        index = (index + 1) % data.length;
        sunpos.applyAxisAngle(axis_z, alt * deg);
        sunpos.applyAxisAngle(axis_y, -azi * deg);
        scene.remove(pointer);
        pointer = new THREE.ArrowHelper(sunpos.clone().normalize(), origin, 10, 0xff00ff);
        scene.add(pointer);
        sun.position.copy(sunpos);
        // console.log(data[index].time);
        // console.log(alt);
        // console.log(-azi);
        // console.log(sunpos);
    }
    requestAnimationFrame(reanimate);
};
requestAnimationFrame(reanimate);

